// Переопределения комнат по видам смет (синхронизируется work_id "estRooms"):
// нет ключа вида — действует дефолт (дом → ROOMS_HOUSE, остальные → ROOMS_BANYA).
let EST_ROOMS={};
function roomsFor(kind){ var c=EST_ROOMS[kind]; return (Array.isArray(c)&&c.length)?c:(kind==="house"?ROOMS_HOUSE:ROOMS_BANYA); }
// Перед первым редактированием комнат вида — материализуем копию дефолта.
function ensureKindRooms(kind){ if(!Array.isArray(EST_ROOMS[kind]))EST_ROOMS[kind]=roomsFor(kind).map(function(r){return {k:r.k,n:r.n,emoji:r.emoji,color:r.color};}); }
const ROOMS_EST=ROOMS_BANYA; // по умолчанию — баня (обратная совместимость)
// Площадь помещения для чистовой работы: по комнате (e.room) и типу из названия (стены/пол/потолок).
function workFillArea(e, specs, kind){
  if(!specs||!Array.isArray(specs.rooms))return null;
  var rk=estRoom(e, kind);
  if(rk==="obshchie")return null;
  var room=specs.rooms.find(function(r){ return estRoom({name:r.name}, kind)===rk; });
  if(!room)return null;
  var s=(e.name||"").toLowerCase(), type=null;
  if(/потол/.test(s))type="ceil";
  else if(/стен/.test(s))type="wall";
  else if(/(?:^|[^а-яё])пол[аы]?(?:[^а-яё]|$)/.test(s)||/напольн/.test(s))type="floor";  // кириллице-безопасно: пол/пола/полы, но не «полки/полков»
  if(!type)return null;
  var c=specRoomCalc(room, specs.height);
  var v=c[type];
  if(!(v>0))return null;
  return { type:type, value:v, room:room.name, label:(type==="wall"?"стены":type==="floor"?"пол":"потолок") };
}
function estRoom(e, kind){
  // Сохранённую комнату используем, только если она из набора текущего типа (баня/дом).
  // Иначе (напр. дом-смета скопирована из бани с банными ключами) — определяем по названию,
  // чтобы работа не выпала из группировки.
  if(e&&e.room&&roomsFor(kind).some(function(rm){return rm.k===e.room;}))return e.room;
  var s=((e&&e.name)||"").toLowerCase(), hits=[];
  if(kind==="house"){
    if(/зал|гостин/.test(s))hits.push("zal");
    if(/спальн/.test(s))hits.push("spalnya");
    if(/санузел|сан\s*узел|туалет|ванн|унитаз|душев/.test(s))hits.push("sanuzel");
    if(/коридор|прихож|тамбур|холл/.test(s))hits.push("koridor");
  } else {
    if(/парн|сауна/.test(s))hits.push("parnaya");
    if(/душев|моечн|\bмойк/.test(s))hits.push("dushevaya");
    if(/туалет|санузел|унитаз/.test(s))hits.push("tualet");
    if(/отдыха|комнат[аы]? отдых|\bко\b/.test(s))hits.push("ko");
    if(/травя?н|фитобоч|фитобар|фитотерап/.test(s))hits.push("travyanaya");
  }
  var r=hits.length===1?hits[0]:"obshchie";
  // Страж: угаданная по названию комната могла быть удалена из набора вида —
  // тогда «Общие», иначе смета выпадет из группировки по комнатам.
  return roomsFor(kind).some(function(rm){return rm.k===r;})?r:"obshchie";
}
