function deepCopy(x){return JSON.parse(JSON.stringify(x));}
// Глубокая копия этапов со СВЕЖИМИ id (этап/работа/материал). Обязательна при
// копировании (новый объект из шаблона, дубль шаблона): иначе копия делит id с
// источником, а флаг покупки purchased[m.id] глобальный → покупка материала в одном
// объекте «протекает» на все объекты из того же шаблона. deepCopy рвёт общие ссылки,
// затем присваиваем новые id на всех трёх уровнях.
function reidStages(stages){
  return deepCopy(stages||[]).map(function(s){
    s.id=gid();
    (s.works||[]).forEach(function(w){ w.id=gid(); (w.mats||[]).forEach(function(m){ m.id=gid(); }); });
    return s;
  });
}

// ─── ХАРАКТЕРИСТИКИ ОБЪЕКТА (помещения + проёмы) ─────────────────────────────
// Хранятся в шаблоне (t.specs) и копируются в объект. Высота потолка — ОДНА общая
// на объект (specs.height). У помещения площади: пол, стены, потолок (все м²).
// Объём помещения = пол × общая высота.
function ensureSpecs(o){
  if(!o.specs||typeof o.specs!=="object"){o.specs={rooms:[],openings:[]};}
  if(!Array.isArray(o.specs.rooms))o.specs.rooms=[];
  if(!Array.isArray(o.specs.openings))o.specs.openings=[];
  if(o.specs.height==null){ var firstH=(o.specs.rooms[0]&&o.specs.rooms[0].h); o.specs.height=(firstH!=null&&firstH!=="")?Number(firstH):2.5; }
  var _H=Number(o.specs.height)||0;
  o.specs.rooms.forEach(function(r){
    if(!r.id)r.id="r"+Math.random().toString(36).slice(2,9);
    // миграция: было поле площади пола → переносим в длину (ширина 1), периметр из стен/высоты
    if(r.w==null&&r.l==null&&(r.floor||r.floor===0)&&r.floor!==""){ r.l=Number(r.floor)||0; r.w=1; }
    if(r.wallLen==null&&(r.wall||r.wall===0)&&r.wall!==""&&_H>0){ r.wallLen=Math.round((Number(r.wall)/_H)*100)/100; }
  });
  return o.specs;
}
// Типовые длины хлыста/доски (м.п.) для конструктора разбивки материала.
const LEN_OPTIONS=[1.5,1.8,2,2.2,2.5,3,4,6];
// Имя материала для объединения в закупке: у не-пачечных отбрасываем хвостовую
// площадь/количество («ОСП 30 м²» / «ОСП 18 м²» → «ОСП»), чтобы они слились в одну
// позицию. У пачек хвостовое «N м²» — это размер упаковки, его не трогаем.
function normMatName(m){
  var n=((m&&m.n)||"").trim();
  if(((m&&m.mode)||"piece")!=="pack"){
    var s=n.replace(/\s+\d+([.,]\d+)?\s*(м²|м2|кв\.?\s*м|м\.п\.?|шт\.?|лист\w*)\.?$/i,"").trim();
    if(s)n=s;
  }
  return n;
}
// Магазины-поставщики, которым готовим ТЗ (PDF) для отправки, а не онлайн-корзину.
// Онлайн (Озон/Лемана/Авито) — покупка по ссылке; остальные — спецификация поставщику.
const TZ_STORES=["Белка","pechki.su","Егорьевск","Славянский мир","Нижний Новгород"];
function isTZStore(s){return TZ_STORES.indexOf(s)>=0;}
// Сумма метража из разбивки по хлыстам [{len,n}] и читаемый текст для примечания.
function breakdownTotal(bd){ return Array.isArray(bd)?Math.round(bd.reduce(function(a,r){return a+(Number(r.len)||0)*(Number(r.n)||0);},0)*100)/100:0; }
function breakdownNote(bd){
  if(!Array.isArray(bd))return "";
  const parts=bd.filter(function(r){return (Number(r.n)||0)>0;}).map(function(r){return numRu(Number(r.n)||0)+"×"+numRu(Number(r.len)||0)+" м";});
  if(!parts.length)return "";
  return parts.join(" + ")+" = "+numRu(breakdownTotal(bd))+" м.п.";
}
function lenSelectOptions(cur){
  const c=Number(cur)||0, has=LEN_OPTIONS.indexOf(c)>=0;
  let o=LEN_OPTIONS.map(function(L){return '<option value="'+L+'"'+(L===c?' selected':'')+'>'+numRu(L)+' м</option>';}).join("");
  if(!has&&c>0)o='<option value="'+c+'" selected>'+numRu(c)+' м</option>'+o;
  return o;
}
