// ─── Факсимиле подписи исполнителя (Кублицкий Ю.Г.) ───
// Прозрачный PNG зашит data-URI: печать идёт в пустом окне (window.open+document.write)
// без origin, а R2/workers.dev в РФ режется — только data-URI гарантированно рендерится.
// data-URI подставляется build-скриптом в строку ниже (плейсхолдер уникален).
const CT_SIGN_IMG="data:image/png;base64,";
// Подпись доступна только для подписанта Кублицкого Ю.Г. (у ИП Петров образца нет).
function ctHasSign(){ const t=ctTplGet(),ex=ctTplExec(); return !!t.signOn && !!CT_SIGN_IMG && ex.k!=="petrov"; }
// Наложить факсимиле поверх линии подписи Исполнителя, если включён тумблер.
// Когда выключено — возвращает исходную линию без изменений (нулевой визуальный эффект).
function ctSignLine(line,h,top,left){
  if(!ctHasSign())return line;
  // Факсимиле «свисает» вниз от линии подписи в пустую часть ячейки (top+height),
  // чтобы высокий росчерк не перекрывал реквизиты/текст выше. Параметры подобраны
  // под пропорции конкретного PNG (высокий: плотное тело ~40% высоты, остальное — росчерк).
  return '<span style="position:relative;display:inline-block">'+line+
    '<img src="'+CT_SIGN_IMG+'" alt="Подпись" style="position:absolute;left:'+(left==null?4:left)+'px;top:'+(top==null?-16:top)+'px;height:'+(h||76)+'px;width:auto;pointer-events:none">'+
  '</span>';
}
// Тумблер «вставить подпись» для формы шаблона.
function ctSignToggle(){
  const t=ctTplGet(),ex=ctTplExec();
  if(ex.k==="petrov")
    return '<div style="margin-bottom:8px;font-size:11px;color:#9aabbf;background:#f8fafc;border:1px dashed #d0dae8;border-radius:8px;padding:8px 10px">✍️ Факсимиле подписи есть только для Кублицкого Ю.Г. Для ИП Петров подпись ставится вручную.</div>';
  const on=!!t.signOn;
  return '<div style="margin-bottom:8px">'+
    '<button data-a="ct-tpl-sign" style="width:100%;padding:9px;border-radius:8px;cursor:pointer;font-size:12.5px;font-weight:700;border:1.5px solid '+(on?"#27ae60":"#dde6f0")+';background:'+(on?"#27ae60":"#fff")+';color:'+(on?"#fff":"#7a9aaa")+'">'+(on?"✍️ Подпись Кублицкого Ю.Г. вставлена ✓":"✍️ Вставить подпись Кублицкого Ю.Г.")+'</button>'+
    '<div style="font-size:10px;color:#9aabbf;margin-top:4px">Факсимиле встанет на линию «Исполнитель» в договоре (п. 12) и в акте. Заказчик подписывает вручную.</div>'+
  '</div>';
}

